WITH base AS (SELECT id, store_name, city, region, opened_date, sqft, CASE WHEN sqft >= 17098 THEN 'High' WHEN sqft >= 4760 THEN 'Medium' ELSE 'Low' END AS sqft_level, DAY(opened_date) AS opened_date_day FROM stores WHERE opened_date >= DATE '2023-09-25') SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, CASE WHEN sqft >= 13041 THEN 'LARGE' ELSE 'SMALL' END AS sqft_tier, COUNT(CASE WHEN city = 'Singapore' THEN 1 END) AS singapore_count, COUNT(DISTINCT region) AS distinct_regions, ROUND(AVG(opened_date_day), 2) AS avg_opened_date_day, GROUPING_ID() AS gid FROM base GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', opened_date), CASE WHEN sqft >= 13041 THEN 'LARGE' ELSE 'SMALL' END), (DATE_TRUNC('YEAR', opened_date)), ());
